import {run, type Settings} from "glyph-engine";
import {langs, tabs, type Lang} from "./rendering/content";
import {cellHit, lineHeightPx, program, scrollBy, selectTab, setLang, ui} from "./rendering/program";

const root = document.getElementById("root")!;

const savedLang = () => {
    try {
        return localStorage.getItem("lang");
    } catch {
        return null;
    }
};
const wanted = new URLSearchParams(location.search).get("lang") ?? savedLang();
setLang(langs.includes(wanted as Lang) ? (wanted as Lang) : "en");

ui.reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
ui.hover = matchMedia("(hover: hover)").matches;

const fontFamily = '"0xProtoNerdFontMono", monospace';
// Fixed at load: the engine measures cells once and never re-measures.
const small = innerWidth < 768;
const fontSize = small ? "13px" : "16px";
await Promise.all([
    document.fonts.load(`${fontSize} ${fontFamily}`, "A\uf1bb"),
    document.fonts.load(`bold ${fontSize} ${fontFamily}`, "A"),
]);

const settings: Settings = {
    element: root,
    cols: 0,
    rows: 0,
    once: false,
    fps: 12,
    renderer: "text",
    allowSelect: false,
    restoreState: false,
    backgroundColor: "var(--crust)",
    fontFamily,
    fontSize,
    // Below the font content height so inline backgrounds overlap and leave no seams between rows.
    lineHeight: small ? "15px" : "18px",
};

run(program, settings);

// Not "click": rows redraw every frame, and browsers drop a click whose pressed element was replaced.
// Capture keeps the release on root for the same reason. It is still a user gesture for popup blockers.
let press = {x: 0, y: 0};
root.addEventListener("pointerdown", (e) => {
    root.setPointerCapture(e.pointerId);
    press = {x: e.clientX, y: e.clientY};
});
root.addEventListener("pointerup", (e) => {
    const still = Math.hypot(e.clientX - press.x, e.clientY - press.y) < 10;
    if (e.button === 0 && still) cellHit(e.clientX, e.clientY)?.run();
});

root.addEventListener("wheel", (e) => {
    e.preventDefault();
    scrollBy(Math.sign(e.deltaY) * 3);
}, {passive: false});

window.addEventListener("keydown", (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const page = ui.viewRows - 2;
    const actions: Record<string, () => void> = {
        j: () => scrollBy(1), ArrowDown: () => scrollBy(1),
        k: () => scrollBy(-1), ArrowUp: () => scrollBy(-1),
        h: () => selectTab(ui.tab - 1), ArrowLeft: () => selectTab(ui.tab - 1),
        l: () => selectTab(ui.tab + 1), ArrowRight: () => selectTab(ui.tab + 1),
        PageDown: () => scrollBy(page), " ": () => scrollBy(page), PageUp: () => scrollBy(-page),
        g: () => scrollBy(-Infinity), Home: () => scrollBy(-Infinity),
        G: () => scrollBy(Infinity), End: () => scrollBy(Infinity),
        L: () => setLang(langs[(langs.indexOf(ui.lang) + 1) % langs.length]!),
    };
    const number = Number(e.key);
    if (number >= 1 && number <= tabs.length) selectTab(number - 1);
    else if (actions[e.key]) actions[e.key]!();
    else return;
    e.preventDefault();
});

// Touch: drag scrolls, a mostly horizontal swipe switches tab.
let touch = {x: 0, y: 0, lastY: 0};
root.addEventListener("touchstart", (e) => {
    const t = e.touches[0]!;
    touch = {x: t.clientX, y: t.clientY, lastY: t.clientY};
}, {passive: true});
root.addEventListener("touchmove", (e) => {
    const y = e.touches[0]!.clientY;
    const rows = Math.trunc((touch.lastY - y) / lineHeightPx());
    if (rows) {
        scrollBy(rows);
        touch.lastY = y;
    }
}, {passive: true});
// Capture and stop: the engine's own touchend handler reads e.touches[0], which is empty here, and throws.
root.addEventListener("touchend", (e) => {
    e.stopImmediatePropagation();
    const t = e.changedTouches[0]!;
    const dx = t.clientX - touch.x;
    if (Math.abs(dx) > 70 && Math.abs(dx) > 2 * Math.abs(t.clientY - touch.y)) {
        selectTab(ui.tab - Math.sign(dx));
    }
}, {capture: true});
