import type {Buffer, Context, Coord, Cursor, Program} from "glyph-engine";
import {buffer as cells, drawbox} from "glyph-engine";
import {langs, page, semanticHtml, strings, tabs, type Lang, type Line} from "./content";
import {shade, type Scene} from "./shader";
import {FROZEN_TIME, growthAt, rasterize, SCALE, START_TIME, viewYaw, type Overlay} from "./tree";

const {drawBox} = drawbox;

export const ui = {lang: "en" as Lang, tab: 0, scroll: 0, maxScroll: 0, viewRows: 10, reduced: false, hover: true, narrow: false};

type Hit = { x0: number; x1: number; y: number; run: () => void };
let hits: Hit[] = [];
let cellWidth = 8;
let lineHeight = 16;

export const selectTab = (index: number) => {
    ui.tab = (index + tabs.length) % tabs.length;
    ui.scroll = 0;
};
export const scrollBy = (rows: number) => {
    ui.scroll = Math.max(0, Math.min(ui.maxScroll, ui.scroll + rows));
};
export const setLang = (lang: Lang) => {
    ui.lang = lang;
    ui.scroll = 0;
    document.documentElement.lang = lang;
    document.getElementById("cv")!.innerHTML = semanticHtml(lang);
    const url = new URL(location.href);
    if (lang === "en") url.searchParams.delete("lang");
    else url.searchParams.set("lang", lang);
    history.replaceState(null, "", url);
    try {
        localStorage.setItem("lang", lang);
    } catch {
        // Storage can be blocked; the choice then lasts for this page only.
    }
};
const hitIn = (x: number, y: number) => hits.find((h) => h.y === y && x >= h.x0 && x < h.x1);
export const cellHit = (px: number, py: number) => hitIn(Math.floor(px / cellWidth), Math.floor(py / lineHeight));
export const lineHeightPx = () => lineHeight;

const openUrl = (url: string) => {
    if (url.startsWith("mailto:")) location.href = url;
    else window.open(url, "_blank", "noopener");
};

// Wide: window right, tree left. Otherwise: tree in a strip above a full-width window.
export function layout(cols: number, rows: number, aspect = 0.5, bare = false) {
    if (bare) {
        const horizon = Math.round(rows * 0.8);
        const base = horizon + 2;
        const radius = Math.min((base - 2) / 2, cols * aspect * 0.5);
        return {win: {x: 0, y: 0, w: 0, h: 0}, horizon, tree: {cx: cols / 2, cy: base - radius, radius}};
    }
    if (cols >= 130) {
        const w = Math.min(104, cols - 44);
        const x = cols - w - 3;
        const horizon = Math.round(rows * 0.8);
        const base = horizon + 2;
        const radius = Math.min((base - 2) / 2, x * aspect * 0.5);
        return {
            win: {x, y: 2, w, h: rows - 3},
            horizon,
            tree: {cx: x / 2, cy: base - radius, radius},
        };
    }
    const strip = rows >= 26 ? Math.max(5, Math.min(12, Math.round(rows * 0.25))) : 0;
    const roomy = cols >= 84;
    const w = roomy ? Math.min(104, cols - 4) : cols;
    const y = 1 + strip;
    return {
        win: {x: Math.floor((cols - w) / 2), y, w, h: rows - y - (roomy ? 1 : 0)},
        horizon: strip ? y - Math.max(1, Math.round(strip * 0.2)) : rows - 2,
        tree: {cx: cols / 2, cy: y - 0.5 - (strip - 0.5) / 2, radius: (strip - 0.5) / 2},
    };
}

const scene: Scene = {hole: {x: 0, y: 0, w: 0, h: 0}, time: 0, horizon: 0, yaw: 0, cx: 0, base: 0, shadow: 0};
let overlay: Overlay = {depth: new Float32Array(0), chars: [], colors: [], kinds: new Uint8Array(0), light: new Float32Array(0)};
let tiltY = 0;

function pre(context: Context, cursor: Cursor) {
    const {cols, rows} = context;
    const aspect = context.metrics.aspect;
    const {win, tree, horizon} = layout(cols, rows, aspect, tabs[ui.tab]!.scene);
    const time = ui.reduced ? FROZEN_TIME : context.time + START_TIME;
    if (ui.hover) {
        tiltY = (cursor.x / cols - 0.5) * 1.2;
    }
    if (overlay.depth.length !== cols * rows) {
        overlay = {depth: new Float32Array(cols * rows), chars: new Array(cols * rows), colors: new Array(cols * rows), kinds: new Uint8Array(cols * rows), light: new Float32Array(cols * rows)};
    }
    Object.assign(scene, {hole: win, time, horizon, yaw: viewYaw(time, tiltY), cx: tree.cx, base: tree.cy + tree.radius, shadow: tree.radius * SCALE * growthAt(time)});
    rasterize({cols, rows, aspect, ...tree, time, tiltY}, overlay);
}

function main(coord: Coord, context: Context) {
    return shade(coord, context, scene, overlay);
}

let cacheKey = "";
let cached: Line[] = [];
function pageLines(width: number) {
    const key = `${ui.lang}:${ui.tab}:${width}`;
    if (key !== cacheKey) {
        cacheKey = key;
        cached = page(tabs[ui.tab]!, width, ui.lang);
    }
    return cached;
}

function post(context: Context, cursor: Cursor, buffer: Buffer) {
    const {cols, rows} = context;
    cellWidth = context.metrics.cellWidth;
    lineHeight = context.metrics.lineHeight;
    ui.narrow = cols < 84;
    const mx = Math.floor(cursor.x);
    const my = Math.floor(cursor.y);
    (context.settings.element as HTMLElement).style.cursor = hitIn(mx, my) && ui.hover ? "pointer" : "default";
    hits = [];

    const put = (text: string, x: number, y: number, style: object, maxX = cols) => {
        for (const char of text) {
            if (x >= maxX) return x;
            cells.merge({char, ...style}, x++, y, buffer, cols, rows);
        }
        return x;
    };

    // waybar-style tab row
    cells.setRect({char: " ", color: "var(--text)", backgroundColor: "var(--mantle)", fontWeight: "normal"}, 0, 0, cols, 1, buffer, cols, rows);
    const compact = cols < 106;
    const slot = compact ? Math.floor(cols / tabs.length) : 0;
    let x = compact ? 0 : 1;
    tabs.forEach((tab, i) => {
        const [name, short] = tab.names[ui.lang];
        const label = compact ? `${tab.icon} ${short}` : ` ${i + 1}:${tab.icon} ${name} `;
        const width = compact ? slot : [...label].length;
        const active = i === ui.tab;
        const hover = ui.hover && my === 0 && mx >= x && mx < x + width;
        cells.setRect({char: " ", backgroundColor: active ? "var(--blue)" : "var(--mantle)"}, x, 0, width, 1, buffer, cols, rows);
        put(label.slice(0, width + 1), x, 0, {
            color: active ? "var(--crust)" : hover ? "var(--blue)" : "var(--subtext0)",
            backgroundColor: active ? "var(--blue)" : "var(--mantle)",
            fontWeight: active ? "bold" : "normal",
        }, x + width);
        hits.push({x0: x, x1: x + width, y: 0, run: () => selectTab(i)});
        x += width;
    });
    if (!compact) {
        const now = new Date();
        const clock = ` ${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")} `;
        put(clock, cols - [...clock].length, 0, {color: "var(--subtext0)", backgroundColor: "var(--mantle)"});
    }

    const tab = tabs[ui.tab]!;
    if (tab.scene) {
        ui.maxScroll = 0;
        return;
    }

    const {win} = layout(cols, rows, context.metrics.aspect);
    drawBox("", {
        x: win.x, y: win.y, width: win.w, height: win.h, borderStyle: "round", shadowStyle: "none",
        paddingX: 0, paddingY: 0, color: "var(--blue)", backgroundColor: "var(--base)", fontWeight: "normal",
    }, buffer, cols, rows);

    let langX = win.x + win.w - 2 - langs.length * 4;
    put(` nicolas@medis: ${tab.dir} `, win.x + 2, win.y, {color: "var(--text)", fontWeight: "bold"}, langX);
    for (const lang of langs) {
        const active = lang === ui.lang;
        const hover = ui.hover && my === win.y && mx >= langX && mx < langX + 4;
        put(` ${lang} `, langX, win.y, {
            color: active ? "var(--crust)" : hover ? "var(--blue)" : "var(--subtext0)",
            backgroundColor: active ? "var(--blue)" : "var(--base)",
            fontWeight: active ? "bold" : "normal",
        });
        hits.push({x0: langX, x1: langX + 4, y: win.y, run: () => setLang(lang)});
        langX += 4;
    }

    const innerX = win.x + 2;
    const innerY = win.y + 1;
    const innerW = win.w - 5; // borders, padding, scrollbar
    const innerH = win.h - 2;
    const lines = pageLines(innerW);
    ui.viewRows = innerH;
    ui.maxScroll = Math.max(0, lines.length - innerH);
    ui.scroll = Math.min(ui.scroll, ui.maxScroll);

    const revealed = ui.reduced || ui.tab !== 0 ? Infinity : context.frame * 3;
    for (let row = 0; row < innerH; row++) {
        const index = row + ui.scroll;
        const line = lines[index];
        if (!line || index > revealed) break;
        const y = innerY + row;
        let at = innerX;
        for (const span of line) {
            const start = at;
            const width = [...span.text].length;
            const hover = !!span.url && ui.hover && my === y && mx >= start && mx < start + width;
            at = put(span.text, at, y, {
                color: hover ? "var(--crust)" : span.color,
                backgroundColor: hover ? "var(--sky)" : "var(--base)",
                fontWeight: span.bold ? "bold" : "normal",
            }, innerX + innerW);
            if (span.url) {
                const {url} = span;
                hits.push({x0: start, x1: at, y, run: () => openUrl(url)});
            }
        }
        if (index === lines.length - 1 && Math.floor(context.time / 500) % 2 === 0) {
            put("█", at, y, {color: "var(--text)"});
        }
    }

    if (ui.maxScroll > 0) {
        const thumb = Math.max(1, Math.round((innerH * innerH) / lines.length));
        const top = Math.round((ui.scroll / ui.maxScroll) * (innerH - thumb));
        const barX = win.x + win.w - 2;
        for (let i = 0; i < innerH; i++) {
            const on = i >= top && i < top + thumb;
            put(on ? "┃" : "│", barX, innerY + i, {color: on ? "var(--blue)" : "var(--surface1)"});
        }
    }

    const hint = ui.narrow ? strings[ui.lang].swipe : strings[ui.lang].keys;
    const percent = ui.maxScroll ? ` ${Math.round((ui.scroll / ui.maxScroll) * 100)}% ` : "";
    const bottom = win.y + win.h - 1;
    put(hint, win.x + 2, bottom, {color: "var(--overlay1)"}, win.x + win.w - 2);
    put(percent, win.x + win.w - 2 - percent.length, bottom, {color: "var(--overlay1)"});
}

export const program: Program = {pre, main, post};
