const SWATCHES = [c.red, c.peach, c.yellow, c.green, c.teal, c.blue, c.mauve];

function fetchLines(width: number, lang: Lang): Line[] {
    const tree: Line[] = [
        [{text: "nicolas", color: c.blue, bold: true}, {text: "@", color: c.text}, {text: "medis", color: c.blue, bold: true}],
        [{text: "─".repeat(13), color: c.dim}],
        [{text: "MedisOS 1.0 (Ąžuolas)", color: c.green, bold: true}],
        ...strings[lang].tree.map(([key, value], i): Line => {
            const [color, branch] = BRANCHES[i]!;
            return [
                {text: `${branch} ${key.padEnd(8)}`, color, bold: key === key.toUpperCase()},
                {text: value, color: c.text},
            ];
        }),
        [],
        [{text: SWATCHES.map(() => "███").join(""), color: c.text}],
    ];
    tree[tree.length - 1] = SWATCHES.map((color) => ({text: "███", color}));

    const fits = width >= LOGO_WIDTH + 38;
    const rows: Line[] = fits
        ? LOGO.map((art, i) => [{text: art.padEnd(LOGO_WIDTH), color: i < TRUNK_START ? c.green : c.peach, bold: true}, ...(tree[i] ?? [])])
        : tree;
    const about = data[lang].sections[SECTION.summary]!.blocks.flatMap((b) => blockLines(b, width));
    return [...rows, [], ...about, []];
}

function contactLines(width: number, lang: Lang): Line[] {
    const {header} = data[lang];
    const linkRows = header.filter((b) => b.links.length).map((b): Line => {
        const label = b.text;
        const url = b.links[0]!.url;
        const shown = url.replace(/^mailto:|^https:\/\/(www\.)?/, "");
        return [{text: `\uf0c1 ${shown === label ? label : `${label.padEnd(10)} ${shown}`}`, color: c.link, url}];
    });
    const place = header.filter((b) => b.kind === "text" && !b.links.length && !b.text.startsWith("NICOLAS"));
    return [
        [{text: `## ${strings[lang].contact}`, color: c.blue, bold: true}],
        [],
        ...place.flatMap((b) => blockLines(b, width)),
        [],
        ...linkRows,
        [],
    ];
}

