// ys zsh theme prompt, then the tab's output, then a live prompt the renderer blinks.
export function page(tab: Tab, width: number, lang: Lang): Line[] {
    const prompt: Line = [
        {text: "# ", color: c.blue, bold: true}, {text: "nicolas", color: c.teal},
        {text: " @ ", color: c.dim}, {text: "medis", color: c.green},
        {text: " in ", color: c.dim}, {text: tab.dir, color: c.yellow, bold: true},
    ];
    return [
        prompt,
        [{text: "$ ", color: c.red, bold: true}, {text: tab.cmd, color: c.text}],
        [],
        ...tab.body(width, lang),
        prompt,
        [{text: "$ ", color: c.red, bold: true}],
    ];
}

// Plain semantic copy of the CV for screen readers and crawlers.
export function semanticHtml(lang: Lang) {
    const {header, sections} = data[lang];
    const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
    const inline = ({text, links}: Block) => {
        let out = "", last = 0;
        for (const l of links) {
            out += `${esc(text.slice(last, l.start))}<a href="${esc(l.url)}">${esc(text.slice(l.start, l.end))}</a>`;
            last = l.end;
        }
        return out + esc(text.slice(last));
    };
    const body = sections.map(({title, blocks}) =>
        `<section><h2>${esc(title)}</h2>${blocks.map((b) =>
            b.kind === "role" ? `<h3>${inline(b)}</h3>` : `<p>${inline(b)}</p>`).join("")}</section>`).join("");
    return `<h1>${esc(header[0]?.text ?? "")}</h1>${header.slice(1).map((b) => `<p>${inline(b)}</p>`).join("")}${body}`;
}
