import type {Context, Coord} from "glyph-engine";
import {num, sdf, vec2} from "glyph-engine";
import {fillAt, shadeColor, type Overlay} from "./tree";

const density = " .:-=+*#%@";
const GRASS = ".,'\"";
const FIELD_OF_VIEW = 2.4;

export type Hole = { x: number; y: number; w: number; h: number }; // covered by the window, not shaded
export type Scene = { hole: Hole; time: number; horizon: number; yaw: number; cx: number; base: number; shadow: number };

type Rgb = [r: number, g: number, b: number];
const mix = (a: Rgb, b: Rgb, t: number): Rgb => [0, 1, 2].map((i) => a[i]! + (b[i]! - a[i]!) * t) as Rgb;
const css = ([r, g, b]: Rgb) => `rgb(${r | 0},${g | 0},${b | 0})`;
const SKY_TOP: Rgb = [47, 58, 95], SKY_MID: Rgb = [91, 121, 184], SKY_LOW: Rgb = [169, 192, 232];
const GROUND_FAR: Rgb = [86, 112, 90], GROUND_NEAR: Rgb = [38, 51, 44];
const FAR_RANGE: Rgb = [106, 123, 168], NEAR_RANGE: Rgb = [79, 91, 128];
const WHITE: Rgb = [255, 255, 255], GRASS_INK: Rgb = [166, 209, 137], SHADOW: Rgb = [14, 20, 18];

// One colour per row, so the gradients are built once instead of per cell.
let bandsKey = -1;
let sky: string[] = [];
let clouds: string[][] = [];
let ground: string[] = [];
let grass: string[] = [];
let shaded: string[][] = [];
function buildBands(rows: number, horizon: number) {
    bandsKey = rows * 4096 + horizon;
    const skyRgb = Array.from({length: rows}, (_, row) => {
        const t = Math.min(1, row / Math.max(1, horizon));
        return t < 0.6 ? mix(SKY_TOP, SKY_MID, t / 0.6) : mix(SKY_MID, SKY_LOW, (t - 0.6) / 0.4);
    });
    sky = skyRgb.map(css);
    clouds = skyRgb.map((rgb) => [0.08, 0.16, 0.24, 0.32].map((t) => css(mix(rgb, WHITE, t))));
    const groundRgb = Array.from({length: rows}, (_, row) => mix(GROUND_FAR, GROUND_NEAR, Math.max(0, row - horizon) / Math.max(1, rows - horizon)));
    ground = groundRgb.map(css);
    grass = groundRgb.map((rgb) => css(mix(rgb, GRASS_INK, 0.4)));
    shaded = groundRgb.map((rgb) => [0.2, 0.4, 0.6].map((t) => css(mix(rgb, SHADOW, t))));
}

// Heights in 0..1 around the full circle, so the ranges wrap as the view turns. Layer 0 is far, 1 near.
export function ridge(angle: number, layer: 0 | 1) {
    const height = layer === 0
        ? 0.55 + 0.25 * Math.sin(3 * angle + 1) + 0.15 * Math.sin(7 * angle + 2.3) + 0.05 * Math.sin(19 * angle + 0.7)
        : 0.3 + 0.18 * Math.sin(5 * angle + 4) + 0.1 * Math.sin(11 * angle + 1) + 0.04 * Math.sin(23 * angle);
    return Math.max(0, Math.min(1, height));
}

function mountain(x: number, y: number, cols: number, scene: Scene) {
    const tall = Math.max(2, scene.horizon * 0.22);
    for (const layer of [1, 0] as const) {
        const angle = (x / cols) * FIELD_OF_VIEW - scene.yaw * (layer ? 1.6 : 1);
        const height = ridge(angle, layer);
        const top = Math.round(scene.horizon - height * tall * (layer ? 0.7 : 1));
        if (y < top) continue;
        const base = layer ? NEAR_RANGE : FAR_RANGE;
        if (y > top) return {char: " ", color: css(base), backgroundColor: css(base), fontWeight: "normal"};
        const step = FIELD_OF_VIEW / cols;
        const slope = ridge(angle + step, layer) - ridge(angle - step, layer);
        return {
            char: slope > 0.015 ? "/" : slope < -0.015 ? "\\" : "^",
            color: layer === 0 && height > 0.78 ? css(WHITE) : css(mix(base, WHITE, 0.3)),
            backgroundColor: css(base),
            fontWeight: "normal",
        };
    }
    return null;
}

// Marks are fixed to the world and orbit the tree with the view.
function field(x: number, y: number, aspect: number, scene: Scene) {
    const reach = y - scene.horizon + 1;
    const across = ((x - scene.cx) * aspect * 12) / reach;
    const along = 6 / reach - 1;
    const sin = Math.sin(scene.yaw), cos = Math.cos(scene.yaw);
    const u = Math.floor((across * cos - along * sin) * 6);
    const v = Math.floor((along * cos + across * sin) * 6);
    const hash = num.fract(Math.sin(u * 127.1 + v * 311.7) * 43758.5453);
    // Soft blob under the crown, so the tree sits on the ground instead of floating over it.
    const dx = (x - scene.cx) * aspect / (scene.shadow * 1.1 || 1);
    const dy = (y - scene.base) / (scene.shadow * 0.22 + 0.5);
    const dark = 1 - dx * dx - dy * dy;
    return {
        char: hash > 0.8 ? GRASS[Math.floor(hash * 41) % GRASS.length] : " ",
        color: grass[y],
        backgroundColor: dark > 0 && scene.shadow > 0 ? shaded[y]![Math.floor(dark * 3)] : ground[y],
        fontWeight: "normal",
    };
}

// The original warped-circle pattern, tinted into thin cloud.
function warp(coord: Coord, context: Context, time: number) {
    const t = time * 0.0001;
    const m = Math.min(context.cols, context.rows);
    const a = context.metrics.aspect;
    let st = {
        x: ((2 * (coord.x - context.cols / 10 - Math.sin(t * 0.5) * context.cols * 0.2)) / m) * a,
        y: (2 * (coord.y - context.rows / 10 - Math.cos(t * 0.5) * context.rows * 0.2)) / m,
    };
    st = vec2.rot(st, 0.6 * Math.sin(0.62 * t) * vec2.length(st) * 2.5);
    st = vec2.rot(st, t * 0.2);
    const s = num.map(Math.sin(t), -1, 1, 0.5, 1.8);
    const pt = {x: num.fract(st.x * s) - 0.5, y: num.fract(st.y * s) - 0.5};
    const d = sdf.sdCircle(pt, 0.5 * Math.sin(0.5 * t + st.x * 0.2) + 0.5);
    const width = 0.05 + 0.3 * Math.sin(t);
    const k = num.smoothstep(width, width + 0.2, Math.sin(10 * d + t));
    const c = (1 - Math.exp(-3 * Math.abs(d))) * k;
    return {
        char: density[Math.floor(c * 5)],
        color: clouds[coord.y]![Math.min(3, Math.floor(c * 4))],
        backgroundColor: sky[coord.y],
        fontWeight: "normal",
    };
}

export function shade(coord: Coord, context: Context, scene: Scene, tree: Overlay) {
    const {hole, horizon} = scene;
    if (coord.x >= hole.x && coord.x < hole.x + hole.w && coord.y >= hole.y && coord.y < hole.y + hole.h) {
        return " ";
    }
    if (bandsKey !== context.rows * 4096 + horizon) buildBands(context.rows, horizon);
    const back = coord.y >= horizon
        ? field(coord.x, coord.y, context.metrics.aspect, scene)
        : mountain(coord.x, coord.y, context.cols, scene) ?? warp(coord, context, scene.time);
    if (tree.depth[coord.index]! < Infinity) {
        const light = tree.light[coord.index]!;
        const fill = fillAt(tree, coord.index, context.cols);
        return {
            ...back,
            char: tree.chars[coord.index],
            color: shadeColor(tree.colors[coord.index]!, light),
            backgroundColor: fill ? shadeColor(fill, light) : back.backgroundColor,
            fontWeight: "bold",
        };
    }
    return back;
}
